        walk(d.get('operationalLayers',[]))
    elif it.get('type')=='Feature Collection':
        d=j(f'https://www.arcgis.com/sharing/rest/content/items/{iid}/data')
        for fl in d.get('layers',[]): print('   FC',fl.get('layerDefinition',{}).get('name'),fl.get('layerDefinition',{}).get('geometryType'),len(fl.get('featureSet',{}).get('features',[])))
    elif it.get('url'): urls.append((it['title'],it['url']))
    for t,u in urls:
        try:
            s=j(u)
            if 'layers' in s and not s.get('geometryType'):
                for l in s['layers']:
                    lu=f"{u.rstrip('/')}/{l['id']}"
                    if l.get('geometryType','esriGeometryPolyline')=='esriGeometryPolyline' or l.get('geometryType') is None:
                        try: c=j(lu+'/query',where='1=1',returnCountOnly='true').get('count')
                        except Exception: c='?'
                        print('   ',l.get('name'),l.get('geometryType'),c,lu)
            else:
                c=j(u+'/query',where='1=1',returnCountOnly='true').get('count') if s.get('geometryType') else ''
                print('   ',t,s.get('geometryType'),c,u, s.get('error',''))
        except Exception as e: print('   ERR',u,e)
